        lastRequests: null,
        samples: [],
        seenFaSegments: {},
        resumeDetected: false,
        resumeStages: [],
        feedbackLoopCount: 0,
        rateLimitRetryCount: 0,
        rateLimitDetected: false,
        timeoutCount: 0
