    }
    if (Array.isArray(a) !== Array.isArray(b)) { diffs.push(path + ': array mismatch'); return false; }
    var keys = Object.keys(a).concat(Object.keys(b).filter(function(k) { return !(k in a); }));
    keys.forEach(function(k) { deepEqual(a[k], b[k], path + '.' + k, diffs); });
    return diffs.length === 0;
}

