function sleepMilliseconds(ms) {
    ms = parseInt(ms, 10) || 0;
    if (ms <= 0) return;
    // Java bridge first (dmtools GraalJS); busy-wait fallback for the
    // node test harness (same pattern as aiTeammateTokenUsageReporter).
    if (typeof Java !== 'undefined' && Java.type) {
        try {
