function deepEqual(a, b, path, diffs) {
    if (a === b) return true;
    if (typeof a !== typeof b || a === null || b === null || typeof a !== 'object') {
        if (String(a) !== String(b)) diffs.push(path + ': ' + JSON.stringify(a) + ' !== ' + JSON.stringify(b));
